{{-- Approval: the % of rated tickets that got 👍, a bar (green 👍 / red 👎) and the counts. $a = ['rated', 'good', 'pct'] --}}
@if ($a['pct'] === null)<span class="muted">No ratings yet</span>
@else<span class="ap" title="{{ $a['good'] }} 👍 and {{ $a['rated'] - $a['good'] }} 👎 = {{ $a['pct'] }}% approval"><b class="approval {{ $a['pct'] >= 90 ? 'ok' : ($a['pct'] >= 75 ? 'warn' : 'bad') }}">{{ rtrim(rtrim(number_format($a['pct'], 1), '0'), '.') }}%</b><span class="ap-split"><span style="width:{{ $a['pct'] }}%"></span></span><span class="ap-n">👍 {{ $a['good'] }} · 👎 {{ $a['rated'] - $a['good'] }}</span></span>@endif
